type StructInfo struct {
	Name     string `json:"name"`
	Fields   []Field `json:"fields"`
}

type Field struct {
	Type  string `json:"type"`
	Name  string `json:"name"`
	Doc   string `json:"doc,omitempty"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <program> <source_file_path> <struct_name>")
		os.Exit(1)
	}

	sourceFilePath := os.Args[1]
	structName := os.Args[2]

	// Parse the source file
	file, err := parser.ParseFile(token.NewFileSet(), sourceFilePath, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Error parsing file %s: %v\n", sourceFilePath, err)
		return
	}

	// Extract fields from the struct definition
	var structInfo StructInfo
	ast.Walk(func(node ast.Node) error {
		switch n := node.(type) {
		case *ast.Field:
			field := &StructInfo{
				Name: n.Name.Value,
			}
			for _, t := range n.Type.List {
				if t.Kind == token.TYPE && t.Name != "string" { // Assuming non-string types are primitive types
					field.Fields = append(field.Fields, Field{
						Type:  t.Type.String(),
						Name:  n.Name.Value,
						Doc:   "",
					})
				}
			}
			structInfo.Fields = append(structInfo.Fields, field)
		default:
			return nil
		}
		return nil
	}, file)

	// Generate Avro schema
	schema, err := json.MarshalIndent(&structInfo, "", "\t")
	if err != nil {
		fmt.Printf("Error marshalling JSON: %v\n", err)
		return
	}

	// Write the schema to a file
	outputPath := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outputPath, schema, 0644)
	if err != nil {
		fmt.Printf("Error writing to file %s: %v\n", outputPath, err)
		return
	}

	fmt.Printf("Avro schema generated successfully at %s\n", outputPath)
}
